/**
 * Announces a write the plan refused, so the owners hear about it whoever
 * tried. Kept apart from `billing.limit_exceeded`: the usage recount publishes
 * that one as a 90% warning and refuses nothing.
 */
export async function announceLimitRefusal(
  orgId: OrgId,
