/**
 * Resolves the in-app page a record lives on, so alerts and search hits link to routes the app actually serves.
 *
 * Each resolver returns `null` when the record is gone, and the caller links nowhere rather than to a dead page.
 *
 * Must call (do not reimplement): issuePath, projectPath, settingsPath
 */
import { issuePath, projectPath, settingsPath } from "@/lib/url";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import type { CommentId, IssueId, OrgId, ProjectId } from "@/types/common";

export async function issueHref(
  orgId: OrgId,
  issueId: IssueId,
): Promise<string | null> {
  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (!issue) return null;

  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  const org = await orgRepo.findOrgById(orgId);
  if (!project || !org) return null;

  return issuePath(org.slug, project.slug, issue.number);
}

/** A comment is read on its issue's page. */
export async function commentHref(
  orgId: OrgId,
  commentId: CommentId,
): Promise<string | null> {
  const comment = await commentRepo.findCommentById(orgId, commentId);
  return comment ? issueHref(orgId, comment.issueId) : null;
}

export async function projectHref(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<string | null> {
  const project = await projectRepo.findProjectById(orgId, projectId);
  const org = await orgRepo.findOrgById(orgId);
  if (!project || !org) return null;

  return projectPath(org.slug, project.slug);
}

/** One section of the org settings, e.g. `members` or `billing`. */
export async function settingsHref(
  orgId: OrgId,
  section: string,
): Promise<string | null> {
  const org = await orgRepo.findOrgById(orgId);
  return org ? settingsPath(org.slug, section) : null;
}

