): Promise<string | null> {
  const project = await projectRepo.findProjectById(orgId, projectId);
  const org = await orgRepo.findOrgById(orgId);
  if (!project || !org) return null;

  return projectPath(org.slug, project.slug);
}

/** One section of the org settings, e.g. `members` or `billing`. */
export async function settingsHref(
  orgId: OrgId,
  section: string,
): Promise<string | null> {
  const org = await orgRepo.findOrgById(orgId);
  return org ? settingsPath(org.slug, section) : null;
}

