          body: `You were mentioned on issue ${payload.issueId}`,
          href,
          actorId: payload.actorId,
        },
      );
    }
  });

  // The owners hear about the new member; the person who joined does not.
  subscribe("member.joined", async (payload) => {
    const org = requireFound(
      await orgRepo.findOrgById(payload.orgId),
      "Organization",
      payload.orgId,
    );
    const href = await settingsHref(payload.orgId, "members");
    if (href === null) return;

    const owners = (await memberRepo.listOwnerIds(payload.orgId)).filter(
      (ownerId) => ownerId !== payload.userId,
    );
    await notify(payload.orgId, "member_joined", owners, {
      title: "A new member joined",
      body: `${payload.userId} joined ${org.name} as ${payload.role}`,
      href,
      actorId: payload.userId,
    });
  });

  // A refused write reaches the owners whoever attempted it, the owner
  // included. Repeats for a resource stay silent while the first is unread.
  subscribe("billing.limit_refused", async (payload) => {
    const org = requireFound(
      await orgRepo.findOrgById(payload.orgId),
      "Organization",
      payload.orgId,
    );
    const project =
      payload.projectId === null
        ? null
        : await projectRepo.findProjectById(payload.orgId, payload.projectId);
    const href = await settingsHref(payload.orgId, "billing");
    if (href === null) return;

    const owners = await memberRepo.listOwnerIds(payload.orgId);
    await notify(
      payload.orgId,
      "plan_limit_reached",
      owners,
      {
        title: "Plan limit reached",
        body: planLimitBody(payload.resource, project?.key ?? null),
        href,
        actorId: payload.actorId,
      },
      { includeActor: true, dedupeUnread: true },
    );
  });
}

