import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { emit } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as issueService from "@/server/services/issue-service";
import * as notificationService from "@/server/services/notification-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { MemberId } from "@/types/common";
import { toIsoTimestamp } from "@/types/common";

let cleanup: () => void;
let tenant: Tenant;
let free: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("verify", "growth");
  free = await createTenant("verify-free", "free");
});

afterAll(() => {
  cleanup();
});

const list = (
  actor: Tenant["actors"][keyof Tenant["actors"]],
  recipient: Tenant["userIds"][keyof Tenant["userIds"]],
  kind: string,
) =>
  notificationService.listNotifications(actor, {
    orgId: tenant.org.id,
    recipientId: recipient,
    unreadOnly: false,
    kind: [kind as never],
    limit: 25,
    cursor: null,
  });

describe("scratch verification", () => {
  it("keeps inboxes and settings personal", async () => {
    await notificationService.notify(
      tenant.org.id,
      "comment_created",
      [tenant.userIds.admin, tenant.userIds.member],
      { title: "t", body: "personal", href: "/x", actorId: tenant.userIds.owner },
    );

    await expect(
      notificationService.listNotifications(tenant.actors.owner, {
        orgId: tenant.org.id,
        recipientId: tenant.userIds.admin,
        unreadOnly: false,
        limit: 25,
        cursor: null,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const adminRow = (
      await notificationService.listNotifications(tenant.actors.admin, {
        orgId: tenant.org.id,
        recipientId: tenant.userIds.admin,
        unreadOnly: false,
        limit: 25,
        cursor: null,
      })
    ).items.find((n) => n.body === "personal");
    expect(adminRow).toBeDefined();

