      leadId: free.userIds.owner,
      color: "#111111",
      targetDate: null,
    };
    await projectService.createProject(free.actors.owner, { ...base, name: "Second", key: "SECD" } as never);

    const refuse = () =>
      projectService.createProject(free.actors.member, { ...base, name: "Third", key: "THRD" } as never);
    await expect(refuse()).rejects.toThrow();
    await expect(refuse()).rejects.toThrow();

    const alerts = () =>
      notificationService.listNotifications(free.actors.owner, {
        orgId: free.org.id,
        recipientId: free.userIds.owner,
        unreadOnly: false,
        kind: ["plan_limit_reached"],
        limit: 25,
        cursor: null,
      });
    const first = await alerts();
    expect(first.items).toHaveLength(1);
    expect(first.items[0]?.href).toBe("/verify-free/settings/billing");

    await notificationService.markRead(free.actors.owner, {
      orgId: free.org.id,
      notificationId: first.items[0]!.id,
    });
    await expect(refuse()).rejects.toThrow();
    expect((await alerts()).items).toHaveLength(2);
  });

  it("links search hits to the pages the app serves", async () => {
    const hits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Searchable",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(hits.items.length).toBeGreaterThan(0);
    expect(hits.items[0]?.href).toMatch(/^\/verify\/projects\/platform\/issues\/\d+$/);
  });
});

